const b=$input.first().json.body;
if (!b || typeof b !== 'object' || Array.isArray(b) || Object.keys(b).sort().join(',') !== 'input,protocol,request_id' || b.protocol !== 'aes-n8n-v1' || typeof b.request_id !== 'string' || !/^[a-f0-9]{32}$/.test(b.request_id)) throw new Error('Invalid AES envelope');
const d=b.input;
if (!d || typeof d !== 'object' || Array.isArray(d)) throw new Error('Invalid AES input');
if (Object.keys(d).length !== 0) throw new Error('Invalid health input');
const result={ready:true};
return [{json:{protocol:'aes-n8n-v1',request_id:b.request_id,execution_id:String($execution.id),result}}];
